arguments.command:
cd /workspace && sed -i 's/if 0 < R < D and outcap < R and (sink not in S):/if 0 < R and outcap < R and (sink not in S):/' tmp/compiler_proto.py && python3 - <<'PY'
import sys,random,time
sys.path.insert(0,'/workspace/tmp')
from compiler_proto import *
random.seed(1)
cnt=0
for n in range(2,10):
 for it in range(100):
  np=random.randint(2,min(6,n))
  C=sorted(random.sample(range(n),np))
  roots={v:random.choice([0,1,2,3]) for v in C}
  if sum(roots.values())==0:roots[C[0]]=1
  D=sum(roots.values())
  links=[]
  for u in range(n):
   for v in range(u+1,n):
    if random.random()<0.4: links.append((u,v))
  env={i:random.randint(0,10) for i in range(len(links))}
  p=1
  cut=find_deficient_cut(n,links,C,roots,p,env)
  try:
   st,target=compile_plan(n,links,C,roots,p,env)
   if cut is not None:
    print('expected denied but prepared',n,it,C,roots,links,env,cut);raise SystemExit
   validate_plan(target,n,links,C,roots,p,env)
  except Exception as e:
   if cut is not None: continue
   print('FAIL',n,it,C,roots,links,env,repr(e));raise
  cnt+=1
 print('n',n,'ok')
print('all compiled validated',cnt)
PY
